const out = document.getElementById("o");
function safeStore(op) {
  try {
    if (op === "save") {
      localStorage.setItem("demo", JSON.stringify({ n: 1 }));
      out.textContent = "Saved";
    } else {
      out.textContent = localStorage.getItem("demo");
    }
  } catch (err) {
    out.textContent = "Sandbox blocked storage — use this API on your own page: " + err.message;
  }
}
document.getElementById("s").onclick = () => safeStore("save");
document.getElementById("l").onclick = () => safeStore("load");
